import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'

import { captureCanvasAction } from '../canvasAnalytics'
import type { CanvasApi } from '../generated/api.schemas'
import { canvasSceneLogic } from './canvasSceneLogic'

export interface CanvasFullscreenLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasFullscreenLogicValues {
    canvas: CanvasApi | null // canvasSceneLogic
    fullscreen: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasFullscreenLogicActions {
    setFullscreen: (fullscreen: boolean) => {
        fullscreen: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface canvasFullscreenLogicMeta {
    key: string
}

export type canvasFullscreenLogicType = MakeLogicType<
    canvasFullscreenLogicValues,
    canvasFullscreenLogicActions,
    CanvasFullscreenLogicProps,
    canvasFullscreenLogicMeta
>

export const canvasFullscreenLogic = kea<canvasFullscreenLogicType>([
    props({} as CanvasFullscreenLogicProps),
    key((props) => props.id),
    path((key) => ['products', 'canvas', 'frontend', 'scene', 'canvasFullscreenLogic', key]),
    connect((props: CanvasFullscreenLogicProps) => ({
        values: [canvasSceneLogic({ id: props.id }), ['canvas']],
    })),
    actions({
        setFullscreen: (fullscreen: boolean) => ({ fullscreen }),
    }),
    reducers({
        fullscreen: [
            false,
            {
                setFullscreen: (_, { fullscreen }) => fullscreen,
            },
        ],
    }),
    listeners(({ actions, values, props, cache }) => ({
        setFullscreen: ({ fullscreen }) => {
            captureCanvasAction('fullscreen_toggle', {
                dashboard_id: props.id,
                channel_id: values.canvas?.channel,
                open: fullscreen,
            })
            if (!fullscreen) {
                cache.disposables.dispose('fullscreen')
                return
            }
            cache.disposables.add(
                () => {
                    const onKeyDown = (event: KeyboardEvent): void => {
                        if (event.key === 'Escape' && !event.defaultPrevented) {
                            actions.setFullscreen(false)
                        }
                    }
                    const onFullscreenChange = (): void => {
                        if (!document.fullscreenElement) {
                            actions.setFullscreen(false)
                        }
                    }
                    window.addEventListener('keydown', onKeyDown)
                    document.addEventListener('fullscreenchange', onFullscreenChange)
                    return () => {
                        window.removeEventListener('keydown', onKeyDown)
                        document.removeEventListener('fullscreenchange', onFullscreenChange)
                        if (document.fullscreenElement) {
                            void document.exitFullscreen().catch(() => {})
                        }
                    }
                },
                'fullscreen',
                { pauseOnPageHidden: false }
            )
            if (!document.fullscreenElement && document.fullscreenEnabled) {
                void document.documentElement.requestFullscreen().catch(() => {})
            }
        },
    })),
])
